export const ticketTypes = pgTable(
  "ticket_types",
  {
    id: integer("id").primaryKey().generatedByDefaultAsIdentity(),
    eventId: integer("event_id")
      .notNull()
      .references(() => events.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    priceCents: integer("price_cents").notNull(),
    capacity: integer("capacity").notNull(),
    sold: integer("sold").notNull().default(0),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    unique("ticket_types_event_id_name_unique").on(t.eventId, t.name),
    check("ticket_types_price_check", sql`${t.priceCents} >= 0`),
    check("ticket_types_capacity_check", sql`${t.capacity} > 0`),
    check("ticket_types_sold_check", sql`${t.sold} >= 0`),
    // The last line of defense against overselling, whatever the code above it does.
    check("ticket_types_sold_within_capacity_check", sql`${t.sold} <= ${t.capacity}`),
  ],
);

export const eventsRepository: EventsRepository = {
  async list(db, query) {
    // Undefined entries are skipped by and(), so each optional filter is one line.
    const conditions = [
      inArray(events.status, query.statuses),
      query.city === undefined ? undefined : eq(sql`lower(${venues.city})`, query.city.toLowerCase()),
      query.categories === undefined ? undefined : inArray(events.category, query.categories),
      query.from === undefined ? undefined : gte(events.startsAt, query.from),
      query.to === undefined ? undefined : lt(events.startsAt, query.to),
      // The GIN index events_search_idx serves this, and websearch_to_tsquery never throws on user input.
      query.q === undefined ? undefined : sql`${events.search} @@ websearch_to_tsquery('english', ${query.q})`,
      query.after === undefined ? undefined : afterCursor(query.sort, query.after),
    ];
    return withVenue(db)
      .where(and(...conditions))
      .orderBy(...orderFor(query.sort))
      .limit(query.limit);
  },
  // ...
};

async reserve(tx, id, quantity) {
  // The WHERE re-checks capacity at the moment of the write, under the row lock UPDATE takes.
  const [updated] = await tx
    .update(ticketTypes)
    .set({ sold: sql`${ticketTypes.sold} + ${quantity}` })
    .where(and(eq(ticketTypes.id, id), sql`${ticketTypes.sold} + ${quantity} <= ${ticketTypes.capacity}`))
    .returning();
  return updated ?? null;
},

async create(user: AuthUser, input: CreateEvent): Promise<EventWithVenue> {
  const { db, events, venues, hooks } = this.#deps;
  if (input.startsAt <= now()) {
    throw new UnprocessableError([{ field: "startsAt", message: "Must be in the future" }]);
  }
  const venue = await venues.findById(db, input.venueId);
  if (venue === null) throw new UnprocessableError([{ field: "venueId", message: `No venue with id ${input.venueId}` }]);

  const created = await withTx(db, async (tx) => {
    // Hooks registered for event.beforeCreate fill in the slug and tidy the title.
    const { draft } = await hooks.run("event.beforeCreate", { draft: { ...input, organizerId: user.id }, actor: user }, tx);
    if (draft.slug === undefined) throw new Error("No event.beforeCreate hook set a slug");
    return events.create(tx, { ...draft, slug: draft.slug });
  });
  return { ...created, venue: { id: venue.id, name: venue.name, city: venue.city, address: venue.address, capacity: venue.capacity } };
}

export function registerEventHooks(hooks: HookRegistry, deps: { events: Pick<EventsRepository, "slugExists"> }): void {
  hooks.before("event.beforeCreate", async (payload, tx) => {
    const title = payload.draft.title.trim();
    // The same tx as the insert, so the check sees this transaction's own writes.
    const slug = await uniqueSlug(tx, deps.events, slugify(title), null);
    return { ...payload, draft: { ...payload.draft, title, slug } };
  });

  hooks.before("event.beforeUpdate", async (payload, tx) => {
    const { event, changes } = payload;
    if (changes.title === undefined) return payload;
    const title = changes.title.trim();
    if (event.status !== "draft") return { ...payload, changes: { ...changes, title } };
    const slug = await uniqueSlug(tx, deps.events, slugify(title), event.id);
    return { ...payload, changes: { ...changes, title, slug } };
  });
}

const userSchema = new Schema<UserDoc, UserModel, UserMethods>(
  {
    email: {
      type: String,
      required: true,
      trim: true,
      lowercase: true,
      match: [/^[^\s@]+@[^\s@]+\.[^\s@]+$/, "{VALUE} is not a valid email"],
    },
    name: { type: String, required: true, trim: true, minlength: 2, maxlength: 80 },
    // select:false keeps the hash out of normal reads; login asks for it with .select("+password").
    password: { type: String, required: true, select: false },
    role: { type: String, enum: USER_ROLES, default: "member" },
    resetTokenHash: { type: String, default: null, select: false },
    resetTokenExpires: { type: Date, default: null, select: false },
  },
  { timestamps: { currentTime: () => now() } },
);
